1	import { useEffect, useRef, useState } from "react";
2	import type { Memo, Visibility } from "@/types/proto/api/v1/memo_service_pb";
3	import { cacheService, memoService } from "../services";
4	import { useEditorContext } from "../state";
5	import type { EditorController } from "../types/editorController";
6	
7	interface UseMemoInitOptions {
8	  editorRef: React.RefObject<EditorController | null>;
9	  memo?: Memo;
10	  cacheKey?: string;
11	  username: string;
12	  autoFocus?: boolean;
13	  defaultVisibility?: Visibility;
14	  defaultCreateTime?: Date;
15	}
16	
17	export const useMemoInit = ({
18	  editorRef,
19	  memo,
20	  cacheKey,
21	  username,
22	  autoFocus,
23	  defaultVisibility,
24	  defaultCreateTime,
25	}: UseMemoInitOptions) => {
26	  const { actions, dispatch } = useEditorContext();
27	  const initializedRef = useRef(false);
28	  const [isInitialized, setIsInitialized] = useState(false);
29	
30	  useEffect(() => {
31	    if (initializedRef.current) return;
32	    initializedRef.current = true;
33	    const key = cacheService.key(username, cacheKey);
34	
35	    if (memo) {
36	      const initialState = memoService.fromMemo(memo);
37	      cacheService.clear(key);
38	      dispatch(actions.initMemo(initialState));
39	    } else {
40	      const cachedContent = cacheService.load(key);
41	      if (cachedContent) {
42	        dispatch(actions.updateContent(cachedContent));
43	      }
44	      if (defaultVisibility !== undefined) {
45	        dispatch(actions.setMetadata({ visibility: defaultVisibility }));
46	      }
47	      if (defaultCreateTime) {
48	        dispatch(actions.setTimestamps({ createTime: defaultCreateTime, updateTime: defaultCreateTime }));
49	      }
50	    }
51	
52	    if (autoFocus) {
53	      setTimeout(() => editorRef.current?.focus(), 100);
54	    }
55	
56	    setIsInitialized(true);
57	  }, [memo, cacheKey, username, autoFocus, defaultVisibility, defaultCreateTime, actions, dispatch, editorRef]);
58	
59	  return { isInitialized };
60	};
